def text(s,y,size=9.6,width=507):
 st=style if size==9.6 else small;p=Paragraph(s,st);w,h=p.wrap(width,1000);p.drawOn(c,44,y-h);return y-h-16
def head(s,y):c.setFillColor(HexColor('#155D75'));c.setFont('Helvetica-Bold',12);c.drawString(44,y,s);return y-9
def pic(name,y,width=507):
 img=ImageReader(str(F/(name+'.png')));w,h=img.getSize();height=width*h/w;c.drawImage(img,44,y-height,width,height);return y-height-9
def foot(num):c.setFont('Helvetica',8);c.setFillColor(HexColor('#5C6D79'));c.drawString(44,24,'Q-SITE Scientific Track | Frozen numerical research | Team hamster');c.drawRightString(552,24,str(num));c.showPage()
c.setFillColor(HexColor('#163C51'));c.setFont('Helvetica-Bold',21);c.drawString(44,801,title);c.setFont('Helvetica',12);c.drawString(44,781,subtitle);c.setFont('Helvetica-Bold',9);c.drawString(44,761,'Team hamster | Shupei Zhang, Yangxin Zhou, Michael Li, Kathy Chen')
