y=head(paras[5][0],y);y=text(paras[5][1],y);y=pic('window_example',y);y=text('Figure 3. The prespecified kappa=.8 window at p=.05 uses exact expectations to isolate noise and preparation effects. All endpoints and both competing response features are retained. Peaks are not selected afterward by proximity to the reference.',y,8)
