slides=[
 dict(title='Noise-Aware ANNNI\nPhase Diagnostics',sub=subtitle,body='Q-SITE 2026 / Scientific Track\nTeam hamster\nShupei Zhang, Yangxin Zhou, Michael Li, Kathy Chen',fig='resource_tradeoff',note='We study how quantum state preparation and noise affect reconstruction of the ANNNI phase diagram. The central result is a tradeoff: fewer entangling gates improve noisy correlations, and mitigation helps under a genuinely matched gate-weighted measurement budget. But neither improvement alone certifies a phase boundary. We keep the failed preparations, detector rejections and floating-scan results in the submission. The notebook contains the full numerical evidence and a lightweight circuit check.',seconds=40),
 dict(title='Model and evidence layers',sub='Periodic N8/N12 circuits; large-size OBC evidence kept separate',body='H = -sum ZZ(nn) + kappa sum ZZ(nnn) - h sum X\nEvery CNOT: target-only depolarizing channel\nR0 interiors / RN finite-size features / Rlarge trends',fig='slide_reference',note='The Hamiltonian has ferromagnetic nearest-neighbor coupling, competing next-nearest-neighbor coupling and a transverse field. We use periodic boundaries for the small circuits. Noise follows every literal CNOT, on its target only, with the same specified channel at all three noise strengths. Reference preparation and folding count as gates. Three evidence layers prevent a detector from grading itself: supported interiors, same-size exact-diagonalization features, and larger-system evidence. Our observables retain every distance and momentum, including the self-correlation background.',seconds=45),
 dict(title='Fewer gates, different tradeoffs',sub='B0 fixed six-layer HVA -> B3 multi-reference adaptive preparation',body=f"Median CNOTs: {b[0]['B0_median_CNOT']:.0f} -> {b[0]['B3_median_CNOT']:.0f}\nIdeal joint passes: {b[0]['B0_joint_pass']}/420 -> {b[0]['B3_joint_pass']}/420\np=.01 correlation error improves at {b[1]['B3_better']}/420 points",fig='resource_tradeoff',note=f"B0 is the original fixed six-layer Hamiltonian variational ansatz. B3 starts from several physical references and grows energy-optimized Pauli rotations, then uses a frozen energy and resource rule. The median CNOT count is halved, from 192 to 96. Ideal joint preparation coverage drops from 407 to 385 out of 420, so the method does not win on every metric. At noise probability one percent, mean maximum correlation error falls from {b[1]['B0_mean_max_C_error']:.4f} to {b[1]['B3_mean_max_C_error']:.4f}, with improvement at 402 coordinates. This is an observable result, not phase-label accuracy.",seconds=45),
 dict(title='Three noise levels, one diagnostic',sub='Frozen D3; exact expectations; identical 420-point grid',body='Colors: estimated phase-like regions\nCrosses: ideal preparation failed\nUnassigned and degraded are separate classes',fig='slide_phases',note='These are the required three noise maps, alongside the same detector applied to ED data. The method, grid and legend remain fixed across noise levels. The colors show resemblance to physical patterns, not independently validated truth at every coordinate. Crosses indicate failed ideal preparation without hiding the label. Our notebook separately displays single-repeat finite-shot maps and equal-shots mitigation maps. It also shows where independent region labels exist. We never extend the smaller equal-resource cohort into a full equal-resource map.',seconds=45),
 dict(title='Mitigation at equal CNOT-shots',sub='45 fixed coordinates / 32 repeats / unchanged 17-component MSE',body=f"G = 100,000 x original CNOT count\nRaw / SV: 100k shots; ZNE: 33,334\nZNE MSE decrease: {reduction[.01]:.2f}% / {reduction[.05]:.2f}%",fig='equal_resource',note=f"Equal shot counts alone favor extrapolation with more noisy gates. We therefore match the sum of shots times literal CNOTs at each coordinate. Raw and symmetry verification use one hundred thousand shots, whereas quadratic ZNE uses thirty-three thousand three hundred and thirty-four shots shared across the three folds. The integer gate-weighted costs match exactly. At p=.01 and .05 the mean ED-target MSE falls by {reduction[.01]:.2f} and {reduction[.05]:.2f} percent. Each of the 45 coordinate means improves. ZNE worsens all 45 at zero noise. It reduces bias while increasing sampling error, and only six coordinates have independent phase-interior labels.",seconds=55),
 dict(title='Better observables, unstable features',sub='Six complete 17-point windows; five references pass peak selection',body='kappa=.5 fails reference peak selection\nEndpoints, multiple peaks and branch effects retained\nMatching is finite-size evidence, not a phase certificate',fig='window_example',note='The prespecified kappa point eight window illustrates the distinct outcomes of observable reconstruction and response-feature matching. These curves use exact expectations so shot fluctuations cannot explain every failure. All six windows were actually executed. Five reference features are resolvable; the kappa point five reference fails the frozen peak-selection criterion. At strong noise, the equal-shots raw result matches roughly three of those five windows when averaged over measurement repeats, and extrapolation does not improve that aggregate. We retain endpoint and multiple-peak warnings, preparation failures and real same-coordinate branch comparisons. A match with no listed warning is still not proof of a thermodynamic transition.',seconds=50),
 dict(title='Extensions expose the limits',sub='H6 is a physical/domain-wall union, not the six-layer HVA',body=f"N8 low-field passes: {low['B3']['joint_pass']}/48 -> {low['H6']['joint_pass']}/48, with more resources\nN12 difficult/control transfer: {n12['B3']['joint_pass']}/36 vs {n12['H6']['joint_pass']}/36\nDynamics, multiple detectors and mitigation retained",fig='extensions',note='The newer physical and domain-wall construction improves selected joint passes in the independent low-field confirmation subset, from 27 to 37 out of 48. However, median CNOTs increase from 32 to 127 and objective calls increase by about seven and a half times. H6 therefore is not an equal-cost universal winner. Its transfer to the N12 difficult/control set is weaker than B3. The five extension topics remain in the package: larger circuits, multiple detectors, mitigation, dynamics, and the floating-phase search. The negative transfer result is preserved rather than removed from the final story.',seconds=45),
 dict(title='What the evidence supports',sub='A reproducible observable result with explicit phase-diagram limits',body='Lower-CNOT preparation helps noisy correlations\nEqual-resource ZNE reduces bias, not every failure\nZero supported floating samples',fig='floating_evidence',note='The controlled large-system slice supports an antiphase control at field point three and a paramagnetic-side control at point seven. Fields point four and point four two five have conflicting size, entropy and Friedel results. The final evidence contains zero supported floating samples and zero established transition brackets. A timed-out high-bond-dimension continuation is not evidence against a phase. Our conclusion is therefore specific: lower-gate preparation and resource-controlled mitigation improve observable reconstruction, while reliable boundary inference needs stronger evidence. The submission ships saved joint counts, gate tables, reproducible figures, and separate deterministic, physical and random-replay checks.',seconds=45)
]
if "--text-and-report-only" not in sys.argv:
 prs=Presentation();prs.core_properties.author='Team hamster; Shupei Zhang, Yangxin Zhou, Michael Li, Kathy Chen';prs.slide_width=Inches(13.333);prs.slide_height=Inches(7.5)
